    ctx.fillStyle='rgba(204,246,241,.72)';for(let i=0;i<210;i++){const z=-5-(((i*47)%55+55-flightParticleShift)%55),x=((i*97)%211/211-.5)*11,y=((i*67)%199/199-.5)*6,p=point(x,y,z);if(p.x<0||p.x>w||p.y<0||p.y>h)continue;ctx.beginPath();ctx.arc(p.x,p.y,Math.max(.5,Math.min(2,p.scale*.035)),0,Math.PI*2);ctx.fill()}
