  const labSources={"Grid Arangment.py": "\"\"\"Create a 9 x 9 catalogue from two selected Rhino objects.\"\"\"\nimport random\nimport rhinoscriptsyntax as rs\n\nGRID = 9\nSPACING = 25\nORIGIN = [0, 0, 0]\n\n\ndef main():\n    first = rs.GetObject(\"Select object 01\")\n    second = rs.GetObject(\"Select object 02\")\n    if not first or not second:\n        return\n    rng = random.Random(6110)\n    rs.EnableRedraw(False)\n    try:\n        for row in range(GRID):\n            for column in range(GRID):\n                a = rs.CopyObject(first)\n                b = rs.CopyObject(second)\n                angle = column * 5\n                scale_a = 0.9 + 0.2 * rng.random()\n                scale_b = 1.0 + row * 0.1\n                mirrored = rng.random() > 0.5\n                a = rs.RotateObject(a, ORIGIN, angle)\n                a = rs.ScaleObject(a, ORIGIN, [scale_a] * 3)\n                b = rs.ScaleObject(b, ORIGIN, [scale_b] * 3)\n                if mirrored:\n                    b = rs.MirrorObject(b, ORIGIN, [1, 0, 0])\n                position = [250 + SPACING * row, 9 + SPACING * column, 0]\n                rs.MoveObject(a, position)\n                rs.MoveObject(b, position)\n                rs.AddText(\"01 rot {} / scale {:.2f}\".format(angle, scale_a),\n                           [position[0], position[1] - 8, 0], 0.9)\n                rs.AddText(\"02 scale {:.2f} / mirror {}\".format(scale_b, \"yes\" if mirrored else \"no\"),\n                           [position[0], position[1] - 11, 0], 0.9)\n    finally:\n        rs.EnableRedraw(True)\n\n\nif __name__ == \"__main__\":\n    main()\n", "catalog chenxi.py": "\"\"\"Create a 10 x 10, three-object scale and rotation catalogue.\"\"\"\nimport random\nimport rhinoscriptsyntax as rs\n\nGRID = 10\nSPACING = 200\nORIGIN = [0, 0, 0]\n\n\ndef main():\n    objects = [rs.GetObject(\"Select object {:02d}\".format(i)) for i in (1, 2, 3)]\n    if not all(objects):\n        return\n    rng = random.Random(6110)\n    rs.EnableRedraw(False)\n    try:\n        for row in range(GRID):\n            for column in range(GRID):\n                copies = [rs.CopyObject(object_id) for object_id in objects]\n                angle = column\n                factor = 1.0 + row * 0.1\n                mirrored = rng.random() > 0.5\n                copies[0] = rs.RotateObject(copies[0], ORIGIN, angle)\n                copies = [rs.ScaleObject(object_id, ORIGIN, [factor] * 3) for object_id in copies]\n                if mirrored:\n                    copies[1] = rs.MirrorObject(copies[1], ORIGIN, [0, 1, 0])\n                position = [SPACING * row, SPACING * column, 0]\n                rs.MoveObjects(copies, position)\n                rs.AddText(\"01 rot {} / scale {:.2f}\".format(angle, factor),\n                           [position[0], position[1] - 58, 0], 5)\n                rs.AddText(\"02 scale {:.2f} / mirror {}\".format(factor, \"yes\" if mirrored else \"no\"),\n                           [position[0], position[1] - 77, 0], 5)\n                rs.AddText(\"03 scale {:.2f}\".format(factor),\n                           [position[0], position[1] - 96, 0], 5)\n    finally:\n        rs.EnableRedraw(True)\n\n\nif __name__ == \"__main__\":\n    main()\n", "Class Rectangle.py": "\"\"\"Probabilistically subdivide a closed rectangular Rhino polyline.\"\"\"\nimport random\nimport rhinoscriptsyntax as rs\n\nMIN_AREA = 5.0\nCHANCE = 0.9\nMAX_DEPTH = 10\nMAX_COPIES = 1500\n\n\ndef subdivide(parent, depth, rng, count):\n    area = rs.CurveArea(parent)\n    if not area or area[0] <= MIN_AREA or depth >= MAX_DEPTH:\n        return\n    corners = rs.PolylineVertices(parent)\n    if not corners or len(corners) < 4:\n        return\n    for corner in corners[:4]:\n        if count[0] >= MAX_COPIES:\n            return\n        child = rs.ScaleObject(parent, corner, [0.5, 0.5, 1.0], True)\n        if not child:\n            continue\n        count[0] += 1\n        if rng.random() < CHANCE:\n            subdivide(child, depth + 1, rng, count)\n\n\ndef main():\n    rectangle = rs.GetObject(\"Select a closed rectangular polyline\", 4)\n    if not rectangle:\n        return\n    if not rs.IsPolyline(rectangle) or not rs.IsCurveClosed(rectangle):\n        print(\"The selected curve must be a closed rectangular polyline.\")\n        return\n    points = rs.PolylineVertices(rectangle)\n    if not points or len(points) not in (4, 5):\n        print(\"The selected polyline needs exactly four corners.\")\n        return\n    rs.EnableRedraw(False)\n    try:\n        subdivide(rectangle, 0, random.Random(6110), [0])\n    finally:\n        rs.EnableRedraw(True)\n\n\nif __name__ == \"__main__\":\n    main()\n", "Drone Catalogue EMMANUEL.py": "\"\"\"Make nine coherent variations of a selected object group.\"\"\"\nimport random\nimport rhinoscriptsyntax as rs\n\nGRID = 3\nSPACING = 25\nPIVOT = [0, 0, 0]\n\n\ndef main():\n    source = rs.GetObjects(\"Select the drone component group\")\n    if not source:\n        return\n    rng = random.Random(6110)\n    rs.EnableRedraw(False)\n    try:\n        for row in range(GRID):\n            for column in range(GRID):\n                copies = [rs.CopyObject(object_id) for object_id in source]\n                angle = column * 5\n                factor = 0.9 + 0.2 * rng.random()\n                mirrored = rng.random() > 0.5\n                copies = [rs.RotateObject(object_id, PIVOT, angle) for object_id in copies]\n                copies = [rs.ScaleObject(object_id, PIVOT, [factor] * 3) for object_id in copies]\n                if mirrored:\n                    copies = [rs.MirrorObject(object_id, PIVOT, [1, 0, 0]) for object_id in copies]\n                position = [250 + SPACING * row, 9 + SPACING * column, 0]\n                rs.MoveObjects(copies, position)\n                rs.AddText(\"Group rot {} / scale {:.2f}\".format(angle, factor),\n                           [position[0], position[1] - 8, 0], 0.9)\n                rs.AddText(\"Mirrored: {}\".format(\"yes\" if mirrored else \"no\"),\n                           [position[0], position[1] - 11, 0], 0.9)\n    finally:\n        rs.EnableRedraw(True)\n\n\nif __name__ == \"__main__\":\n    main()\n", "Drone Catalogue GPT Joined Objects.py": "\"\"\"Compare two selected objects in a 3 x 3 variation grid.\"\"\"\nimport random\nimport rhinoscriptsyntax as rs\n\nGRID = 3\nSPACING = 25\nORIGIN = [0, 0, 0]\n\n\ndef main():\n    first = rs.GetObject(\"Select first object\")\n    second = rs.GetObject(\"Select second object\")\n    if not first or not second:\n        return\n    rng = random.Random(6110)\n    rs.EnableRedraw(False)\n    try:\n        for row in range(GRID):\n            for column in range(GRID):\n                a = rs.CopyObject(first)\n                b = rs.CopyObject(second)\n                factor_a = 0.9 + 0.2 * rng.random()\n                factor_b = 1.0 + row * 0.1\n                angle = column * 5\n                mirrored = rng.random() > 0.5\n                a = rs.ScaleObject(a, ORIGIN, [factor_a] * 3)\n                b = rs.RotateObject(b, ORIGIN, angle)\n                b = rs.ScaleObject(b, ORIGIN, [factor_b] * 3)\n                if mirrored:\n                    b = rs.MirrorObject(b, ORIGIN, [1, 0, 0])\n                position = [250 + SPACING * row, 9 + SPACING * column, 0]\n                rs.MoveObject(a, position)\n                rs.MoveObject(b, position)\n                rs.AddText(\"01 scale {:.2f}\".format(factor_a),\n                           [position[0], position[1] - 8, 0], 0.9)\n                rs.AddText(\"02 rot {} / scale {:.2f} / mirror {}\".format(\n                    angle, factor_b, \"yes\" if mirrored else \"no\"),\n                    [position[0], position[1] - 11, 0], 0.9)\n    finally:\n        rs.EnableRedraw(True)\n\n\nif __name__ == \"__main__\":\n    main()\n", "Drone Catalogue GPT.py": "\"\"\"Compare two component groups across a 3 x 3 catalogue.\"\"\"\nimport random\nimport rhinoscriptsyntax as rs\n\nGRID = 3\nSPACING = 25\nPIVOT = [50, 0, 0]\n\n\ndef main():\n    first_group = rs.GetObjects(\"Select first component group\")\n    second_group = rs.GetObjects(\"Select second component group\")\n    if not first_group or not second_group:\n        return\n    rng = random.Random(6110)\n    rs.EnableRedraw(False)\n    try:\n        for row in range(GRID):\n            for column in range(GRID):\n                first = [rs.CopyObject(object_id) for object_id in first_group]\n                second = [rs.CopyObject(object_id) for object_id in second_group]\n                angle = column * 5\n                factor_a = 0.9 + 0.2 * rng.random()\n                factor_b = 1.0 + row * 0.1\n                mirrored = rng.random() > 0.5\n                first = [rs.RotateObject(object_id, PIVOT, angle) for object_id in first]\n                first = [rs.ScaleObject(object_id, PIVOT, [factor_a] * 3) for object_id in first]\n                second = [rs.ScaleObject(object_id, PIVOT, [factor_b] * 3) for object_id in second]\n                if mirrored:\n                    second = [rs.MirrorObject(object_id, PIVOT, [1, 0, 0]) for object_id in second]\n                position = [250 + SPACING * row, 9 + SPACING * column, 0]\n                rs.MoveObjects(first + second, position)\n                rs.AddText(\"Group 01 rot {} / scale {:.2f}\".format(angle, factor_a),\n                           [position[0], position[1] - 8, 0], 0.9)\n                rs.AddText(\"Group 02 scale {:.2f} / mirror {}\".format(\n                    factor_b, \"yes\" if mirrored else \"no\"),\n                    [position[0], position[1] - 11, 0], 0.9)\n    finally:\n        rs.EnableRedraw(True)\n\n\nif __name__ == \"__main__\":\n    main()\n", "Drone Catalogue.py": "\"\"\"Build a 9 x 9 catalogue around a fixed component group.\"\"\"\nimport random\nimport rhinoscriptsyntax as rs\n\nGRID = 9\nSPACING = 25\nORIGIN = [0, 0, 0]\n\n\ndef main():\n    first = rs.GetObject(\"Select object 01\")\n    second = rs.GetObject(\"Select object 02\")\n    base_group = rs.GetObjects(\"Select the fixed component group\")\n    if not first or not second or not base_group:\n        return\n    rng = random.Random(6110)\n    rs.EnableRedraw(False)\n    try:\n        for row in range(GRID):\n            for column in range(GRID):\n                a = rs.CopyObject(first)\n                b = rs.CopyObject(second)\n                base = [rs.CopyObject(object_id) for object_id in base_group]\n                angle = column * 5\n                factor_a = 0.9 + 0.2 * rng.random()\n                factor_b = 1.0 + row * 0.1\n                mirrored = rng.random() > 0.5\n                a = rs.RotateObject(a, ORIGIN, angle)\n                a = rs.ScaleObject(a, ORIGIN, [factor_a] * 3)\n                b = rs.ScaleObject(b, ORIGIN, [factor_b] * 3)\n                if mirrored:\n                    b = rs.MirrorObject(b, ORIGIN, [1, 0, 0])\n                position = [250 + SPACING * row, 9 + SPACING * column, 0]\n                rs.MoveObjects([a, b] + base, position)\n                rs.AddText(\"01 rot {} / scale {:.2f}\".format(angle, factor_a),\n                           [position[0], position[1] - 8, 0], 0.9)\n                rs.AddText(\"02 scale {:.2f} / mirror {}\".format(\n                    factor_b, \"yes\" if mirrored else \"no\"),\n                    [position[0], position[1] - 11, 0], 0.9)\n    finally:\n        rs.EnableRedraw(True)\n\n\nif __name__ == \"__main__\":\n    main()\n"};
